-- ============================================================================
-- 0001_initial_schema.sql
--
-- Baseline exported from the live Supabase project (avumcgrgngotinmibwxw) on
-- 2026-10-16 by introspecting pg_catalog / information_schema / pg_policies.
-- It reproduces the production schema AS IT WAS, including its known defects
-- (see docs/AUDIT.md §1). Fixes live in later migrations; do not edit this file.
--
-- On the existing remote project this migration is already applied; mark it with:
--   npx supabase migration repair --status applied 0001
-- ============================================================================

-- ─── Functions ──────────────────────────────────────────────────────────────

create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
as $$
begin
  insert into public.profiles (id, email, full_name)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', '')
  );
  return new;
end;
$$;

-- ─── Tables ─────────────────────────────────────────────────────────────────

create table public.profiles (
  id                  uuid primary key references auth.users(id) on delete cascade,
  email               text not null,
  full_name           text,
  avatar_url          text,
  interface_language  text default 'es'
    constraint profiles_interface_language_check
    check (interface_language = any (array['es','en','nl','fr','de'])),
  onboarded           boolean default false,
  onboarding_step     integer default 1,
  current_business_id uuid,
  created_at          timestamptz default now(),
  updated_at          timestamptz default now()
);

create table public.businesses (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete cascade,
  name          text not null,
  type          text not null
    constraint businesses_type_check
    check (type = any (array['restaurant','bar','cafe','hotel','other'])),
  city          text,
  country       text default 'BE',
  address       text,
  phone         text,
  email         text,
  website       text,
  opening_hours jsonb default '{}'::jsonb,
  created_at    timestamptz default now(),
  updated_at    timestamptz default now()
);

alter table public.profiles
  add constraint fk_profiles_current_business
  foreign key (current_business_id) references public.businesses(id) on delete set null;

create table public.tone_configs (
  id                uuid primary key default gen_random_uuid(),
  business_id       uuid not null unique references public.businesses(id) on delete cascade,
  formality         text not null default 'neutral'
    constraint tone_configs_formality_check
    check (formality = any (array['very_informal','informal','neutral','formal','very_formal'])),
  response_length   text not null default 'medium'
    constraint tone_configs_response_length_check
    check (response_length = any (array['short','medium','long'])),
  response_language text not null default 'auto'
    constraint tone_configs_response_language_check
    check (response_language = any (array['auto','es','en','nl','fr','de'])),
  signature         text default '',
  forbidden_phrases text[] default '{}'::text[],
  favorite_phrases  text[] default '{}'::text[],
  updated_at        timestamptz default now()
);

create table public.reviews (
  id               uuid primary key default gen_random_uuid(),
  business_id      uuid not null references public.businesses(id) on delete cascade,
  customer_name    text not null,
  rating           integer not null
    constraint reviews_rating_check check (rating >= 1 and rating <= 5),
  text             text not null,
  language         text default 'es'
    constraint reviews_language_check
    check (language = any (array['es','en','nl','fr','de'])),
  source           text not null default 'manual'
    constraint reviews_source_check
    check (source = any (array['google','facebook','tripadvisor','thefork','manual'])),
  source_url       text,
  source_review_id text,
  review_date      timestamptz not null default now(),
  status           text not null default 'pending'
    constraint reviews_status_check
    check (status = any (array['pending','approved','rejected','published'])),
  created_at       timestamptz default now(),
  updated_at       timestamptz default now()
);

create table public.responses (
  id            uuid primary key default gen_random_uuid(),
  review_id     uuid not null unique references public.reviews(id) on delete cascade,
  text          text not null,
  status        text not null default 'generated'
    constraint responses_status_check
    check (status = any (array['generated','edited','approved','rejected','published','generation_failed'])),
  model_used    text
    -- Defect (A-02): the NULL element makes non-matching values evaluate to
    -- NULL instead of false, so this CHECK never rejects anything.
    constraint responses_model_used_check
    check (model_used = any (array['claude-haiku-4-5','claude-opus-4-7',null::text])),
  tokens_input  integer default 0,
  tokens_output integer default 0,
  edited_text   text,
  created_at    timestamptz default now(),
  approved_at   timestamptz,
  published_at  timestamptz
);

create table public.integrations (
  id                    uuid primary key default gen_random_uuid(),
  business_id           uuid not null references public.businesses(id) on delete cascade,
  provider              text not null
    constraint integrations_provider_check
    check (provider = any (array['google','facebook','tripadvisor','thefork'])),
  status                text not null default 'disconnected'
    constraint integrations_status_check
    check (status = any (array['disconnected','connected','error','expired'])),
  external_account_id   text,
  external_account_name text,
  access_token          text,
  refresh_token         text,
  token_expires_at      timestamptz,
  scopes                text[],
  last_sync_at          timestamptz,
  last_error            text,
  connected_at          timestamptz,
  created_at            timestamptz default now(),
  constraint integrations_business_id_provider_key unique (business_id, provider)
);

create table public.team_members (
  id             uuid primary key default gen_random_uuid(),
  business_id    uuid not null references public.businesses(id) on delete cascade,
  user_id        uuid references auth.users(id) on delete cascade,
  email          text not null,
  role           text not null default 'viewer'
    constraint team_members_role_check
    check (role = any (array['owner','admin','editor','viewer'])),
  invited_at     timestamptz default now(),
  invited_by     uuid references auth.users(id),
  accepted_at    timestamptz,
  last_access_at timestamptz,
  constraint team_members_business_id_email_key unique (business_id, email)
);

create table public.daily_metrics (
  id                      uuid primary key default gen_random_uuid(),
  business_id             uuid not null references public.businesses(id) on delete cascade,
  date                    date not null,
  total_reviews           integer default 0,
  average_rating          numeric,
  pending_count           integer default 0,
  responded_count         integer default 0,
  rejected_count          integer default 0,
  avg_response_time_hours numeric,
  rating_distribution     jsonb default '{}'::jsonb,
  language_distribution   jsonb default '{}'::jsonb,
  top_topics              jsonb default '[]'::jsonb,
  created_at              timestamptz default now(),
  constraint daily_metrics_business_id_date_key unique (business_id, date)
);

-- ─── Indexes ────────────────────────────────────────────────────────────────

create index idx_profiles_email               on public.profiles (email);
create index idx_businesses_user_id           on public.businesses (user_id);
create index idx_tone_configs_business_id     on public.tone_configs (business_id);
create index idx_reviews_business_id          on public.reviews (business_id);
create index idx_reviews_status               on public.reviews (status);
create index idx_reviews_created_at           on public.reviews (created_at desc);
create index idx_reviews_rating               on public.reviews (rating);
create index idx_responses_review_id          on public.responses (review_id);
create index idx_responses_status             on public.responses (status);
create index idx_integrations_business_id     on public.integrations (business_id);
create index idx_integrations_status          on public.integrations (status);
create index idx_team_members_business_id     on public.team_members (business_id);
create index idx_team_members_user_id         on public.team_members (user_id);
create index idx_daily_metrics_business_date  on public.daily_metrics (business_id, date desc);

-- ─── Triggers ───────────────────────────────────────────────────────────────

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

create trigger trigger_profiles_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

create trigger trigger_businesses_updated_at
  before update on public.businesses
  for each row execute function public.set_updated_at();

create trigger trigger_tone_configs_updated_at
  before update on public.tone_configs
  for each row execute function public.set_updated_at();

create trigger trigger_reviews_updated_at
  before update on public.reviews
  for each row execute function public.set_updated_at();

-- ─── Row Level Security ─────────────────────────────────────────────────────

alter table public.profiles      enable row level security;
alter table public.businesses    enable row level security;
alter table public.tone_configs  enable row level security;
alter table public.reviews       enable row level security;
alter table public.responses     enable row level security;
alter table public.integrations  enable row level security;
alter table public.team_members  enable row level security;
alter table public.daily_metrics enable row level security;

-- profiles
create policy "Users can view own profile"   on public.profiles for select using (auth.uid() = id);
create policy "Users can insert own profile" on public.profiles for insert with check (auth.uid() = id);
create policy "Users can update own profile" on public.profiles for update using (auth.uid() = id);

-- businesses
create policy "Users can view own businesses"   on public.businesses for select using (auth.uid() = user_id);
create policy "Users can create own businesses" on public.businesses for insert with check (auth.uid() = user_id);
create policy "Users can update own businesses" on public.businesses for update using (auth.uid() = user_id);
create policy "Users can delete own businesses" on public.businesses for delete using (auth.uid() = user_id);

-- tone_configs
create policy "Users can view tone for own businesses" on public.tone_configs for select
  using (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));
create policy "Users can create tone for own businesses" on public.tone_configs for insert
  with check (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));
create policy "Users can update tone for own businesses" on public.tone_configs for update
  using (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));

-- reviews
create policy "Users can view reviews of own businesses" on public.reviews for select
  using (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));
create policy "Users can create reviews for own businesses" on public.reviews for insert
  with check (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));
create policy "Users can update reviews of own businesses" on public.reviews for update
  using (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));
create policy "Users can delete reviews of own businesses" on public.reviews for delete
  using (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));

-- responses
create policy "Users can view responses of own businesses" on public.responses for select
  using (review_id in (select r.id from public.reviews r join public.businesses b on r.business_id = b.id where b.user_id = auth.uid()));
create policy "Users can create responses for own businesses" on public.responses for insert
  with check (review_id in (select r.id from public.reviews r join public.businesses b on r.business_id = b.id where b.user_id = auth.uid()));
create policy "Users can update responses of own businesses" on public.responses for update
  using (review_id in (select r.id from public.reviews r join public.businesses b on r.business_id = b.id where b.user_id = auth.uid()));

-- integrations
create policy "Users can manage integrations of own businesses" on public.integrations for all
  using (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));

-- team_members
create policy "Users can view team members of own businesses" on public.team_members for select
  using (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));
create policy "Users can manage team members of own businesses" on public.team_members for all
  using (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));

-- daily_metrics
create policy "Users can view metrics of own businesses" on public.daily_metrics for select
  using (business_id in (select businesses.id from public.businesses where businesses.user_id = auth.uid()));
